import numpy as np

def kernel(a, b):
    M, K = a.shape
    K2, N = b.shape
    assert K == K2, "Incompatible dimensions for matrix multiplication"
    result = np.zeros((M, N), dtype=np.float32)
    tile_size_a = 128
    tile_size_b = 512

    for i in range(0, M, tile_size_a):
        for j in range(0, N, tile_size_b):
            for k in range(0, K, tile_size_a):
                # Determine the actual tile size for k
                k_end = min(k + tile_size_a, K)
                # Determine the actual tile size for j
                j_end = min(j + tile_size_b, N)
                # Compute the submatrix product for this tile
                for ii in range(i, min(i + tile_size_a, M)):
                    for jj in range(j, j_end):
                        val = 0.0
                        for kk in range(k, k_end):
                            val += a[ii, kk] * b[kk, jj]
                        result[ii, jj] = val
    return result
